"""Create a local, evidence-first HTML report for the four requested checks."""
import base64
import html
import json
from pathlib import Path

ROOT = Path("visual_test/results/four_criteria")
METRICS = json.loads((ROOT / "metrics.json").read_text())
PUBLIC = json.loads((ROOT / "public_hand_summary.json").read_text())


def embed(path):
    return "data:image/jpeg;base64," + base64.b64encode(path.read_bytes()).decode()


def dump(value):
    return html.escape(json.dumps(value, ensure_ascii=False, indent=2))


old = METRICS["stillness_and_objects"]
new = METRICS["gaze_and_cover"]
public_img = embed(ROOT / "public_contact.jpg")
old_img = embed(Path("visual_test/results/example_video_comparison/contact.jpg"))
new_img = embed(Path("visual_test/results/new_gaze_video/contact.jpg"))
html_text = f'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vision 네 기준 실험 결과</title><style>body{{font:16px/1.7 system-ui,sans-serif;background:#f3f6fa;color:#17243a;margin:0;overflow-wrap:anywhere}}main{{max-width:1120px;margin:auto;padding:22px}}section{{background:#fff;border-radius:14px;padding:24px;margin:20px 0}}h1,h2,h3{{line-height:1.35}}.lead{{font-size:19px}}.bad{{border-left:5px solid #cb4a38;background:#fff0ed;padding:12px}}.partial{{border-left:5px solid #d9951f;background:#fff6e6;padding:12px}}.good{{border-left:5px solid #228362;background:#eaf8f2;padding:12px}}.scroll{{overflow:auto}}table{{border-collapse:collapse;width:100%;table-layout:fixed}}td,th{{border:1px solid #d5deeb;text-align:left;padding:10px;vertical-align:top}}img{{max-width:100%;height:auto;border-radius:9px}}pre{{background:#122238;color:#e6f0ff;padding:16px;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:8px;font-size:13px}}a{{color:#0a5fae}}</style><main><h1>Vision 네 기준 실험 결과</h1><p class="lead"><strong>결론:</strong> 현재 모델은 좌우 비정면의 한 정답 구간은 잡았지만, 5초 양손 정지와 얼굴 가림 전체 구간은 놓쳤다. 분당 손짓 8회 초과는 60초 공개 영상에서 양손을 52.4초 판정할 수 있었는데도 시험용 계수기가 0회를 내어 현재 방식으로 채점하면 안 된다.</p><p>실험 자료: 사용자 제공 예시.mov(62.8초), 사용자 제공 11월 11일 영상(36.2초 표본), <a href="{PUBLIC['source']}">Wikimedia Commons의 CC0 수어 영상</a>(처음 60초). 공개 영상은 발표 제스처의 정답 자료가 아니라 손 움직임 계수기의 기술적 스트레스 테스트다. 동일 영상을 이전 탐색에 사용했으므로 독립 최종 평가라고 부르지 않는다.</p><section><h2>결과 한눈에 보기</h2><div class="scroll"><table><tr><th>요청 기준</th><th>실제 결과</th><th>판단</th></tr><tr><td>1. 5초 이상 양손 정지</td><td>사용자 정답 21–27초. 현재 YOLO 손목 규칙은 21.8–23.8초만 연속 정지(2.0초)로 계산. 사건 0건.</td><td><strong>실패</strong>: 알려진 정지 구간을 놓침.</td></tr><tr><td>2. 분당 손 움직임 8회 초과</td><td>예시.mov 양손 판정 가능 {old['handObservableSeconds']}/62.8초. CC0 1분 영상은 {PUBLIC['handObservableSeconds']}/60초 관찰 가능하지만 시험용 이동→멈춤 계수 0회.</td><td><strong>판단 불가</strong>: 정답 횟수와 움직임 구간 분리가 부족. 8회 초과 Y/N 금지.</td></tr><tr><td>3. 손의 얼굴 가림 시간</td><td>새 영상 장면 검토 24–33초. 모델 손·얼굴 겹침 후보 22.4–26.0초(3.6초), 이후 얼굴 미검출이 길어짐.</td><td><strong>일부만 포착</strong>: 실제 가림 전체 시간 측정 실패.</td></tr><tr><td>4. 얼굴 좌우 방향</td><td>새 영상 사용자 정답 6–14초 한쪽 보기. 얼굴 특징점 비대칭으로 화면 왼쪽 방향 5.4–14.0초(8.6초) 후보.</td><td><strong>이 한 구간은 포착</strong>. 실제 눈동자 시선·60° 각도는 미측정.</td></tr></table></div></section><section><h2>1. 양손 5초 정지: 놓쳤다</h2><p class="bad">사용자가 직접 확인한 정답은 예시.mov 21–27초다. 현재 프로덕션과 같은 YOLO11n-pose 손목·어깨 규칙에서 정지=true는 21.8–23.8초 2.0초만 이어졌다. 21–27초 30개 표본 중 true 10개, false 14개, 관찰 불가 6개였다. 5초 사건은 생성되지 않았다.</p><p>이는 팔이 어깨 높이에 있기 때문이라고 단정할 수 없다. 높이가 아니라 손목의 어깨 대비 <em>변화</em>를 본다. 실제 미세 움직임, 좌표 흔들림, 손목 가림을 분리할 정답 관절 궤적이 없어 실패 원인 비율은 모른다. 이전 MediaPipe 손 모델을 손목에 연결하는 탐색 조합도 사건 0건이었다.</p><img alt="예시 영상의 정지 및 얼굴 가림 장면 표본" src="{old_img}"></section><section><h2>2. 분당 손 움직임: 계수기는 현재 부적합</h2><p class="bad">분당 8회 초과 여부를 아직 판정할 수 없다. 예시.mov의 양손 판정 가능 시간은 {old['handObservableSeconds']}초, 전체의 {old['handCoverageRatio']:.1%}뿐이다. 이를 1분으로 환산하면 관찰 부족을 숨긴다.</p><p>추가로 찾은 CC0 60초 영상은 양손목이 {PUBLIC['bothWristsVisibleSeconds']}초 보이고 시간 이력을 포함해 {PUBLIC['handObservableSeconds']}초 판정 가능했다. 그런데 시험용 규칙(1초 창에서 어깨 대비 손목 이동량 0.04 또는 0.08 초과, 움직임 0.4초 이상, 정지 0.4초로 종료)은 두 설정 모두 <strong>0회</strong>를 냈다. 같은 영상의 300개 표본 중 262개는 정지=false, 38개는 관찰 불가였다. 영상에서 손이 움직이는 모습은 확인되므로 0회를 ‘손짓 없음’으로 해석하면 명백히 잘못된다.</p><p>원인은 현재 정의인 ‘움직였다가 멈춤’에서 <em>멈춤을 언제 사건의 끝으로 볼지</em>가 검증되지 않았기 때문이다. 이어지는 동작은 한 긴 구간으로 합쳐질 수 있다. 공개 영상은 수어와 자전거 접촉이 섞여 있어 발표 손짓 1회 정답을 제공하지 않는다. 손짓 횟수·분당8회 기준은 별도 발표 영상에 사람이 표시한 사건 목록을 만든 후 다시 시험해야 한다.</p><img alt="공개 CC0 영상의 0–50초 표본" src="{public_img}"><p>자료: <a href="{PUBLIC['source']}">원본·CC0 라이선스</a>. 이 보고서에는 원본 동영상 파일을 포함하지 않는다.</p></section><section><h2>3. 손의 얼굴 가림: 앞부분만 포착</h2><p class="partial">장면 검토에서 보이는 새 영상 24–33초 가림에 대해 <code>HAND_FACE_OVERLAP_CANDIDATE</code>는 22.4–26.0초를 냈다. 정답 시작 전 1.6초도 포함됐고, 26초 이후의 긴 가림은 놓쳤다. 26.4–33.2초에는 발표자 얼굴 연결이 사라져 손 외곽과 현재 얼굴 박스의 겹침 자체를 계산하지 못했다.</p><p>눈 주변 겹침을 시선 관찰 불가로 제외한 구간은 22.4–25.8초와 26.2–26.4초다. 그 뒤 얼굴 미검출은 <code>NO_ASSOCIATED_FACE</code>이며 얼굴 가림으로 자동 확정하지 않는다. 따라서 손이 얼굴 근처에 머문 총 시간이나 실제 가림 9초를 현재 JSON으로 정확히 재구성할 수 없다.</p><img alt="새 영상의 비정면 및 얼굴 가림 장면 표본" src="{new_img}"></section><section><h2>4. 얼굴 좌우 방향: 한 구간은 맞지만 각도·시선은 아님</h2><p class="good">YOLO5Face의 양쪽 눈과 코 좌표에서 좌우 비대칭의 <em>부호</em>를 계산했다. 새 영상에서 사용자가 표시한 6–14초 비정면은 화면 왼쪽 방향 5.4–14.0초로 나왔다. 예시.mov에서도 화면 오른쪽 51.4–54.2초, 화면 왼쪽 56.0–57.8초 후보가 나왔다.</p><p>이 분류는 실제 3D 머리 회전 각도나 눈동자 방향이 아니다. ‘화면 왼쪽’은 인물 자신의 좌·우와 반대일 수 있다. 60° 이상 회전 시간 비율과 5%/30% 점수식은 현재 모델 출력으로 계산할 수 없다. 얼굴이 크게 돌아 미검출되면 그 시간은 방향 미상으로 남는다. 카메라가 관객 중앙 근처라는 촬영 조건에서만 얼굴 방향을 관객 방향의 대리 신호로 해석한다.</p></section><section><h2>현재 JSON과 다음 단계</h2><p>백엔드 v4 JSON은 5초 양손 정지 사건, 손·얼굴 겹침 후보, 정면/비정면 시간과 5초 비정면 사건을 담는다. <strong>분당 손 움직임 횟수와 좌우 방향 시간은 아직 실험 계산값일 뿐 백엔드 JSON 필드가 아니다.</strong> 이번 실험 때문에 공용 코드·API·ERD를 바꾸지 않았다.</p><p>우선순위는 ① 21–27초 정지 누락 원인 분리, ② 발표 영상 1분 이상에서 손 움직임 시작·종료의 사람 정답 작성, ③ 얼굴 미검출이 지속될 때 가림/비정면/화면 이탈을 구분하는 추가 검증, ④ 다른 사람·촬영 조건의 좌우 방향 확인이다. 이 절차 전에는 네 기준을 0–100점 채점식으로 사용하지 않는다.</p><h3>실험 집계 JSON</h3><pre>{dump(METRICS)}</pre><h3>공개 손 움직임 시험 JSON</h3><pre>{dump(PUBLIC)}</pre></section></main></html>'''
(ROOT / "report.html").write_text(html_text)
print(ROOT / "report.html")
